import queue  # noqa: F401  (used by the implementation)

import pytest  # noqa: F401


def accepted(cap: int, xs: list[int]) -> int:
    """Count puts accepted by a bounded queue before it is full.

    Create a queue.Queue[int] with capacity cap, then try to put each
    element of xs in order without blocking (put_nowait). Stop at the
    first queue.Full and return the number of puts that succeeded.
    Nothing is ever taken from the queue. A cap of 0 or less means no
    room, so the result is 0 (it is not treated as unbounded).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_fewer_items_than_capacity() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_more_items_than_capacity() -> None:
    assert accepted(2, [1, 2, 3, 4]) == 2


def test_exact_fit() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_empty_input() -> None:
    assert accepted(4, []) == 0


def test_zero_capacity_is_not_unbounded() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity() -> None:
    assert accepted(-1, [1, 2]) == 0


def test_duplicates_are_all_counted() -> None:
    assert accepted(3, [1, 1, 1, 1]) == 3


def test_capacity_one() -> None:
    assert accepted(1, [9, 9, 9]) == 1


def test_large_input() -> None:
    assert accepted(100, list(range(1000))) == 100

